import{z as s,x as i,o as n,c as d,q as A,j as t,D as a,d as B,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"网络效应与标准","description":"","frontmatter":{"title":"网络效应与标准","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/network-standards-io.md","filePath":"econ/network-standards-io.md","lastUpdated":1791063341000}'),p={name:"econ/network-standards-io.md"};function C(h,E,m,D,F,c){const r=i("Mermaid");return n(),d("div",null,[E[2]||(E[2]=A('<h1 id="网络效应与标准" tabindex="-1">网络效应与标准 <a class="header-anchor" href="#网络效应与标准" aria-label="Permalink to &quot;网络效应与标准&quot;">​</a></h1><div class="epigraph"><p>兼容把两家的安装基础加总成一张网；不兼容则把采用变成标准之战。胜出的不必是技术更优的，而是预期先协调到的。</p><footer>—— Katz and Shapiro, AER 1985；Farrell and Saloner 标准化与安装基础；David 对 QWERTY 的路径依赖讨论；对照 Tirole 网络章</footer></div><p><a href="/econ/vertical-restraints">上一课</a>用合同内部化垂直链上的外部性。本课缺口是横向的采用外部性：别人用同一系统，我的支付意愿上升。微观<a href="/econ/network-externalities">网络外部性</a>已经写下实现预期与多均衡。产业组织续课要补的是<strong>标准与兼容作为策略</strong>：厂商何时开放接口、何时为不兼容而战，以及这如何改变进入的沉没与定价。后课把同一逻辑接到平台两边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实现预期下，同一价格可以撑住小网与大网两个不动点。兼容决策把有效网络从「自家用户」改成「可互通用户之和」，需求曲线外移，但独占加价的能力下降。缺口不是再定义 \\(n^e\\)，而是：<strong>兼容是公共品还是封锁工具，标准战锁定的是协调还是质量。</strong> Farrell–Saloner：在位的安装基础可以阻止更优的新技术（过度惯性），也可以因预期跳到新网而抛弃仍有价值的旧网（过度动量）。</p><p>标准可以由协会、主导厂商或政府指定。指定解决协调，也可能把错误技术锁死。本课对照机制，不写标准化学术委员会的程序法。</p><p><span class="marginnote">「过度惯性」是整个市场卡在旧标准上不肯换，哪怕新技术明明更好；「过度动量」是反过来，大家抢着跳去新标准，把还在赚钱的旧网提前扔掉。两个词的主语都是集体的预期，不是某一家厂商的决定。</span></p><h3 id="标准战不是最好技术胜出" tabindex="-1">标准战不是最好技术胜出 <a class="header-anchor" href="#标准战不是最好技术胜出" aria-label="Permalink to &quot;标准战不是最好技术胜出&quot;">​</a></h3><p>把市场结果读成「revealed quality」，会把协调失败叫成效率。键盘布局、录像带格式是教学对照：即使经验争议仍在，理论要点不变——支付意愿含 \\(n^e\\)，早期份额通过预期放大。质量 \\(s\\) 更高但 \\(n^e\\) 更低的系统可以输。上一课纵向约束保护的是服务；本课保护或开放的是接口。</p><p><span class="marginnote">Katz–Shapiro 的兼容是内生策略：混合兼容使有效网络介于完全互通与完全分裂之间。厂商对弱者开放、对强者封闭，可以是均衡，不必诉诸阴谋叙事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套。(1) 需求：\\(v(p,n^e)\\)，不动点 \\(n=n^e\\)。(2) 兼容：两家的 \\(n\\) 是否加总；开放可能收费（接口许可）。(3) 标准：事前协调到单一 \\(n\\)，或让市场裂成多标准。进入：不兼容迫使新厂商自建安装基础，沉没上升——接<a href="/econ/entry-exit-sunk">进入与沉没</a>。定价：大网的勒纳用的是含网络的有效弹性，不是把 \\(n\\) 再叫成质量档。</p>',12)),(n(),t(l,null,{default:a(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20VR%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%9E%82%E7%9B%B4%E5%90%88%E5%90%8C%22%5D%20--%3E%20NET%5B%22%E9%87%87%E7%94%A8%E5%A4%96%E9%83%A8%E6%80%A7%20n%5Ee%22%5D%0A%20%20NET%20--%3E%20COMP%5B%22%E5%85%BC%E5%AE%B9%3A%20%E7%BD%91%E7%BB%9C%E5%8A%A0%E6%80%BB%22%5D%0A%20%20NET%20--%3E%20WAR%5B%22%E4%B8%8D%E5%85%BC%E5%AE%B9%3A%20%E6%A0%87%E5%87%86%E4%B9%8B%E6%88%98%22%5D%0A%20%20COMP%20--%3E%20LOCK%5B%22%E9%94%81%E5%85%A5%E6%88%96%E5%8D%8F%E8%B0%83%22%5D%0A%20%20WAR%20--%3E%20LOCK%0A%20%20LOCK%20--%3E%20PLAT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E4%B8%A4%E8%BE%B9%E4%BA%A4%E5%8F%89%E7%BD%91%E7%BB%9C%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"不要用单边勒纳直接读「免费增值」软件：价格结构可能在补贴采用，那是下一课对象。开放接口的许可费把兼容从「免费公共品」改成可定价的接入；费率过高等于事实不兼容。标准必要专利的诉讼是这条许可费的法律外观，本课不写专利法，只留：接入价格改变有效 \\(n\\)。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"策略互补：你采用提高我采用的收益，预期是状态变量。兼容把互补从「同一品牌」扩到「同一标准」，削弱品牌级网络势力、增强标准级势力。在位拒绝兼容，等于把沉没强加给进入者——纵向排他绑的是渠道，这里绑的是用户基础。路径依赖：早期随机或策略性的份额，通过 \\(n^e\\) 变成后期的需求优势，边际质量改进不必翻转结果。",-1)),(n(),t(l,null,{default:a(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%8E%82%E5%95%86%E9%9D%A2%E5%AF%B9%EF%BC%9A%E5%85%81%E4%B8%8D%E5%85%81%E8%AE%B8%E5%88%AB%E4%BA%BA%E6%8E%A5%E6%88%91%E7%9A%84%E7%BD%91%EF%BC%9F%22%5D%20--%3E%20Q%7B%22%E8%87%AA%E5%AE%B6%E5%AE%89%E8%A3%85%E5%9F%BA%E7%A1%80%E7%9B%B8%E5%AF%B9%E6%9B%B4%E5%A4%A7%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9B%B4%E5%A4%A7%22%7C%20CLOSE%5B%22%E5%B0%81%E9%97%AD%E6%8E%A5%E5%8F%A3%EF%BC%9A%E6%8A%8A%E5%AF%B9%E6%89%8B%E6%8C%A1%E5%9C%A8%E7%BD%91%E5%A4%96%22%5D%0A%20%20CLOSE%20--%3E%20SUNK%5B%22%E5%AF%B9%E6%89%8B%E8%87%AA%E5%BB%BA%E7%BD%91%E7%BB%9C%EF%BC%8C%E8%BF%9B%E5%85%A5%E6%B2%89%E6%B2%A1%E4%B8%8A%E5%8D%87%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9B%B4%E5%B0%8F%22%7C%20OPEN%5B%22%E5%BC%80%E6%94%BE%E6%8E%A5%E5%8F%A3%E6%88%96%E4%BD%8E%E4%BB%B7%E8%AE%B8%E5%8F%AF%EF%BC%9A%E5%80%9F%E5%A4%A7%E7%BD%91%22%5D%0A%20%20OPEN%20--%3E%20SUM%5B%22%E6%9C%89%E6%95%88%E7%BD%91%E7%BB%9C%E5%8A%A0%E6%80%BB%EF%BC%8C%E9%9C%80%E6%B1%82%E5%A4%96%E7%A7%BB%22%5D%0A%20%20SUNK%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%8A%8A%E5%B8%82%E5%9C%BA%E8%AE%A9%E7%BB%99%E6%A0%87%E5%87%86%E7%BA%A7%E5%8A%BF%E5%8A%9B%22%5D%0A%20%20OPEN%20--%3E%20COST%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">直觉类比：小区门口两家便利店办会员卡。若两家会员通用（兼容），顾客只看哪家离得近；若不通用，顾客办卡前先数哪家排队的人多（安装基础）。大店倾向不通用来锁客，小店倾向通用蹭流量——这与图里「网大的封闭、网小的开放」是同一件事。</span></p><p>与差异化定价对照：那里交叉弹性来自偏好异质；这里交叉来自规模进入效用。两套矩阵可以同时存在（不同软件既差异化又联网）。合并模拟若忽略网络，会低估「把两张网合成一张」的涨价或效率。过度惯性与过度动量哪一种更常见，取决于转换成本与预期协调装置，不是取决于哪家的广告预算更大。</p><p><span class="marginnote">Farrell and Saloner 把转换写成带安装基础的动态博弈。本课要的是惯性与动量两种失败，不把全部微分对策写完。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 Katz–Shapiro 的古诺代数，主干已经有网络外部性课。不把标准写成专利法教程，不进限价簿上的撮合。政府强制标准的政治经济只点到「协调装置」，不展开。下一课：交叉网络——一边的 \\(n\\) 进入另一边的需求，价格结构比总价更要紧。</p><p>后课默认：兼容与标准是策略变量，会改进入 \\(F\\) 与有效弹性。看见锁入，先问预期协调，再问质量。</p><p><span class="marginnote">常见误区：看到某个标准赢了就断言它技术最优。正确读法是先问「预期在什么时候协调到了它身上」——早期一点随机的份额会通过 \\(n^e\\) 滚成后期的需求优势，质量差距要大过这层放大才能翻盘。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>兼容加总安装基础，不兼容把采用变成标准之战。</li><li>多均衡下，胜出不必是技术更优。</li><li>拒绝兼容可以提高对手的沉没，类似封锁。</li><li>网络加价不能用单边无 \\(n\\) 的勒纳直接读。</li><li>出处：Katz and Shapiro, <em>AER</em> 1985；Farrell and Saloner；David；Tirole。</li></ul>',9))])}const S=s(p,[["render",C]]);export{f as __pageData,S as default};
